do $do$ declare d jsonb := $j${"topic": {"id": "074d8b95-40b8-583a-9b76-9f324e19c12a", "new": true, "name": "Biology · Digestion, enzymes, circulation and respiration", "summary": "Grade 9 Biology", "sort": 4, "parent": "31ac6b73-081c-5adc-a181-79eca8995b86", "programme": "MYP 4"}, "anchor": "/g9-bio-body-18/", "lessons": [{"id": "87e2f970-239d-516e-9f44-2f868dd15c78", "ext": "G9-BIO-DCR-L1", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 1: The digestive system: structure and function", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-1/", "max": 27, "sort": 11, "msort": 105, "csort": 32, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["3rd", "1st", "5th", "2nd", "6th", "4th"], "tip": "Start at the mouth."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Mouth", "Oesophagus", "Stomach", "Small intestine", "Large intestine", "Pancreas"], "tip": "Follow the food."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["accessory", "not part of the tube", "not in the canal", "outside", "beside"], ["bile", "enzyme", "juice", "secrete", "release", "add"]], "tips": ["What do they add to the gut?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Ingestion", "Digestion", "Absorption", "Assimilation", "Egestion"], "tip": "In, break, through, use, out."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["undigested", "faeces", "not absorbed", "fibre", "never entered"], ["made by cells", "metabolic", "urea", "carbon dioxide", "cells produce", "waste of metabolism"]], "tips": ["Which waste was made inside cells?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["large", "big"], ["insoluble", "cannot dissolve", "not soluble"], ["absorb", "gut wall", "blood", "small", "glucose", "pass through"]], "tips": ["Size and solubility."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["fibre", "roughage"], ["peristalsis", "move", "constipat", "push", "bulk", "faeces"], ["school", "lunch", "menu", "githeri", "vegetables", "whole", "education", "garden", "canteen"]], "tips": ["What does fibre do in the gut?"]}]}, "models": {"1": [["Q1", "If it was a few hours ago it may be in the small intestine, where it is being digested by enzymes and the small molecules are being absorbed into the blood. Older food may be in the large intestine, where water is absorbed."], ["Q2", "Mouth → oesophagus → stomach → small intestine → large intestine → anus."]], "2": [["Q3", "Mouth chews; oesophagus carries; stomach churns; small intestine digests and absorbs; large intestine absorbs water; pancreas makes enzymes."], ["Q4", "They are accessory organs outside the alimentary canal, connected to it by ducts [1]; they secrete substances into the gut: the pancreas makes digestive enzymes and the liver makes bile [1]."]], "3": [["Q5", "Eating: ingestion. Breaking down: digestion. Into blood: absorption. Used by cells: assimilation. Faeces out: egestion."], ["Q6", "Egestion is removing undigested food (faeces) that never entered the body's cells [1]; excretion is removing waste made by cells in metabolism, such as urea and carbon dioxide [1]."]], "4": [["Q7", "Starch molecules are too large [1] and insoluble [1] to pass through the wall of the small intestine, so they must be broken into small soluble glucose molecules that can be absorbed into the blood [1]."]], "5": [["Q8", "Fibre cannot be digested, so it adds bulk to the food in the intestines [1]; the gut muscles can push it along by peristalsis, preventing constipation [1]; schools could serve githeri, whole maize flour and vegetables in school lunches [1]."]], "6": [["Exit ticket", "Small intestine (ileum); large intestine (colon)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "7c19d0b0-1779-5c85-9798-1bf585ad5b05", "ext": "G9-BIO-DCR-L2", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 2: Digestion, absorption and egestion in detail", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-2/", "max": 23, "sort": 12, "msort": 106, "csort": 33, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Mechanical", "Chemical", "Mechanical", "Chemical", "Mechanical"], "tip": "Is a chemical bond broken by an enzyme?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["kill", "bacteria", "microorganisms", "pathogens"], ["ph", "acidic", "protease", "pepsin", "optimum"]], "tips": ["Protection, and helping an enzyme."]}, {"kind": "choice", "id": "q2_1", "q": "Q4", "max": 5, "n": 5, "ans": ["Small intestine", "Stomach", "Mouth", "Small intestine", "Stomach"], "tip": "Follow the meal."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 3, "pts": [["surface area", "microvilli", "many villi", "large area"], ["thin", "one cell", "short distance"], ["capillar", "blood supply", "gradient", "lacteal"]], "tips": ["Area, distance, gradient."]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["surface area", "flatten", "smaller area", "fewer villi"], ["less absorbed", "absorb less", "nutrients", "not absorbed", "less food"]], "tips": ["Flat villi → area?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 2, "pts": [["water", "not absorbed", "lose", "lost"], ["dehydrat", "salts", "death", "die", "dangerous"]], "tips": ["What does the colon normally do?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["visking", "tubing", "bag"], ["starch and amylase", "amylase", "enzyme", "inside"], ["water outside", "test the water", "benedict", "iodine", "test"], ["glucose", "sugar", "outside", "brick red", "no starch", "pass through", "small"]], "tips": ["Gut wall = tubing; blood = water outside."]}]}, "models": {"1": [["Q1", "It starts to taste sweet. Salivary amylase is digesting starch into maltose, a sugar. Chewing breaks the bread into small pieces, giving the enzyme more surface to act on."], ["Q2", "Grinding, churning and emulsifying are mechanical; enzymes are chemical."]], "2": [["Q3", "It kills bacteria and other microorganisms in food [1]; it provides the low pH that the stomach protease (pepsin) needs to work best [1]."], ["Q4", "Bile and absorption: small intestine. Acid and pepsin: stomach. Starch digestion starts: mouth."]], "3": [["Q5", "Millions of villi with microvilli give a very large surface area for absorption [1]; the wall is only one cell thick, so the diffusion distance is short [1]; a dense capillary network carries absorbed food away, keeping the concentration gradient steep [1]."], ["Q6", "Flattened villi have a much smaller surface area [1], so less digested food is absorbed into the blood and the body does not get enough nutrients [1]."]], "4": [["Q7", "In diarrhoea, the colon does not absorb enough water, so a lot of water is lost in faeces [1]; small children quickly become dehydrated and lose salts, which can be fatal; oral rehydration solution replaces them [1]."]], "5": [["Q8", "Fill Visking tubing (the gut wall) [1] with starch solution and amylase [1], and place it in water at 37 °C (the blood); after 20 minutes test the water outside with Benedict's reagent and iodine [1]; I expect sugar (brick red) but no starch outside, because only the small sugar molecules made by digestion pass through the tubing [1]."]], "6": [["Exit ticket", "A wall one cell thick gives a short diffusion distance, so digested food is absorbed quickly."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_0": "Q5", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "020e2b93-bf41-5d33-8697-b5be8f8bfc58", "ext": "G9-BIO-DCR-L3", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 3: Digestive enzymes and the role of surface area", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-3/", "max": 20, "sort": 13, "msort": 107, "csort": 34, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Amylase", "Protease", "Lipase", "Protease", "Amylase"], "tip": "Look at the substrate."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 4, "pts": [["protein"], ["amino acid"], ["fatty acid", "glycerol"], ["pancreas", "stomach"]], "tips": ["Substrate → product; organ."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 4, "pts": [["emulsif", "small droplets", "droplets"], ["surface area", "more area"], ["alkaline", "neutralis"], ["ph", "lipase", "enzymes work", "optimum"]], "tips": ["Size of droplets; pH."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["smaller", "more", "increase", "paste"], ["surface area"], ["enzyme", "protease", "more substrate", "contact", "act on", "collisions"]], "tips": ["Smaller pieces → ?"]}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 1, "pts": [["4.25", "4.3", "about 4", "four"]], "tips": ["0.85 ÷ 0.20."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["fat", "protein", "starch", "all"], ["lipase", "protease", "amylase", "pancreas makes"], ["acid", "stomach", "denatur", "destroy", "low ph"]], "tips": ["What does the pancreas make? What would the stomach do to an enzyme?"]}]}, "models": {"1": [["Q1", "Loose sugar dissolves faster because it has a much larger surface area in contact with the water. In the same way, small pieces of food have more surface for enzymes to act on, so they are digested faster."], ["Q2", "Starch: amylase. Protein: protease. Fat: lipase."]], "2": [["Q3", "Protease breaks down protein [1] into amino acids [1]; lipase breaks down fats into fatty acids and glycerol [1]; both are made in the pancreas (pepsin, a protease, is also made in the stomach) [1]."]], "3": [["Q4", "Bile emulsifies fat into many small droplets [1], increasing the surface area for lipase to act on [1]; bile is alkaline and neutralises the stomach acid [1], giving the higher pH at which lipase works best [1]."]], "4": [["Q5", "The smaller the pieces, the more egg white was digested (0.20 g, 0.42 g, 0.85 g) [1]; smaller pieces have a larger surface area [1], so more protein is in contact with the protease at once and digestion is faster [1]."], ["Q6", "0.85 ÷ 0.20 = 4.25 times more [1]."]], "5": [["Q7", "They would struggle to digest fats, proteins and starch [1], because the pancreas makes lipase, protease and amylase [1]; the coating protects the enzymes from the stomach acid, which would denature them, so they are released in the small intestine [1]."]], "6": [["Exit ticket", "Lipase; fatty acids and glycerol; bile (emulsifies fat)."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "fe4b42c0-c895-5faa-a638-10d656704e08", "ext": "G9-BIO-DCR-L4", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 4: The liver: the body's chemical factory", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-4/", "max": 17, "sort": 14, "msort": 108, "csort": 35, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 3, "n": 3, "ans": ["Hepatic portal vein", "Hepatic artery", "Hepatic vein"], "tip": "Portal = from the gut."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Detoxification", "Deamination", "Glycogen storage", "Bile production", "Storage of vitamins and iron"], "tip": "What is happening to which substance?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["cannot be stored", "not stored", "excess"], ["deamination", "liver", "nitrogen", "amino group"], ["urea", "kidney", "urine"]], "tips": ["Store? Liver? Excrete?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["glycogen", "store"], ["release", "break down", "convert back", "glucagon", "between meals"]], "tips": ["Store and release."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["dry", "drying", "store", "storage", "moisture"], ["sort", "discard", "mouldy", "test", "bags", "hermetic", "clean", "pallets"], ["detox", "toxins", "urea", "glycogen", "functions", "jobs", "poison"], ["build up", "cannot", "fail", "die", "death", "jaundice"]], "tips": ["Prevent mould; then what the liver does."]}]}, "models": {"1": [["Q1", "So that the liver can process what was absorbed: store extra glucose, break down excess amino acids and remove toxins such as alcohol before they reach other organs like the brain."], ["Q2", "From the gut: hepatic portal vein. Oxygenated supply: hepatic artery. Leaving: hepatic vein."]], "2": [["Q3", "Alcohol: detoxification. Amino acids → urea: deamination. Glucose → glycogen: storage. Bile: bile production. Vitamins and iron: storage."]], "3": [["Q4", "The body cannot store excess amino acids [1]; the liver removes their nitrogen-containing part (deamination) [1] and turns it into urea, which is carried to the kidneys and excreted in urine [1]."]], "4": [["Q5", "The liver stores excess glucose as glycogen after meals [1] and breaks glycogen back into glucose to release it into the blood between meals [1]."]], "5": [["Q6", "Dry maize thoroughly before storing it [1] and store it in clean, dry hermetic bags off the floor, throwing away mouldy grain [1]; a damaged liver cannot remove toxins, make urea or control glucose [1], so poisons and waste build up in the blood, which can be fatal [1]."]], "6": [["Exit ticket", "Stores glucose as glycogen; makes bile; deamination of excess amino acids into urea (also detoxification and storing vitamins)."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "b19672d2-aaa5-54c6-bd72-a48ac67f1c94", "ext": "G9-BIO-DCR-L5", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 5: Enzymes: theory, lock and key, temperature and pH", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-5/", "max": 28, "sort": 15, "msort": 109, "csort": 36, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["True", "False", "False", "True"], "tip": "Catalysts are not used up; enzymes are specific."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["4th", "1st", "3rd", "2nd"], "tip": "Fit, bind, react, release."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 3, "pts": [["active site"], ["shape", "complementary", "fit"], ["protein does not fit", "not complementary", "specific", "only starch", "different shape"]], "tips": ["Lock, key, wrong key."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 4, "pts": [["kinetic energy", "move faster", "collisions", "collide"], ["optimum", "fastest", "37", "highest"], ["denature", "active site changes", "shape changes"], ["substrate no longer fits", "cannot bind", "does not fit", "no longer fit", "stops", "falls"]], "tips": ["Collisions, peak, shape change."]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["slow", "less kinetic", "fewer collisions", "not denatured", "inactive"], ["denatured", "permanent", "shape changed", "active site"]], "tips": ["Slow versus broken."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 2, "pts": [["optimum", "ph 2", "acid"], ["denature", "active site", "shape", "does not fit"]], "tips": ["Wrong pH → shape?"]}, {"kind": "choice", "id": "q4_1", "q": "Q8", "max": 3, "n": 3, "ans": ["About pH 2", "About pH 7", "About pH 8"], "tip": "Where does each work?"}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 6, "pts": [["temperature", "20", "30", "40", "50", "60", "water bath"], ["time", "iodine", "starch disappear", "no longer", "orange", "blue-black"], ["volume", "concentration", "same amount"], ["ph", "buffer", "same starch", "same amylase"], ["spotting tile", "every 30", "samples", "stopwatch", "drop"], ["optimum", "37", "40", "denature", "fastest", "because"]], "tips": ["IV, DV, controls, method, hypothesis."]}]}, "models": {"1": [["Q1", "The body's enzymes work best at about 37 °C. At very high temperatures their active sites change shape (they denature), so essential reactions in the brain and other organs stop."], ["Q2", "Enzymes are proteins and biological catalysts; they are not used up and each is specific to one substrate."]], "2": [["Q3", "Collide → complex → reaction → products released."], ["Q4", "Amylase has an active site [1] with a shape complementary to starch, so starch fits like a key in a lock [1]; protein has a different shape and does not fit the active site, so enzymes are specific [1]."]], "3": [["Q5", "As the temperature rises, molecules have more kinetic energy and collide more often, so the rate increases [1]; the rate is fastest at the optimum, about 37 °C for human enzymes [1]; above the optimum the enzyme denatures: its active site changes shape [1], so the substrate no longer fits and the rate falls [1]."], ["Q6", "At 5 °C the enzyme is only inactive because molecules move slowly, so it works again when warmed [1]; at 80 °C it is denatured: its active site shape is permanently changed [1]."]], "4": [["Q7", "Pepsin's optimum pH is about 2 [1]; at pH 8 its active site changes shape (it denatures), so protein no longer fits [1]."], ["Q8", "Stomach: pH 2. Mouth: pH 7. Small intestine: pH 8."]], "5": [["Q9", "Independent variable: temperature (20, 30, 40, 50 and 60 °C in water baths) [1]; dependent variable: time until a sample no longer turns iodine blue-black [1]; controls: the same volume and concentration of starch and amylase [1] and the same pH using a buffer [1]; every 30 s put a drop of the mixture on a spotting tile with iodine and time how long until it stays orange-brown [1]; hypothesis: the reaction will be fastest at about 40 °C, near the optimum, because above it the amylase denatures [1]."]], "6": [["Exit ticket", "Its active site has changed shape, so the substrate no longer fits."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_0": "Q5", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "a84f8bc7-9252-5c11-9359-92e285a0d1a4", "ext": "G9-BIO-DCR-L6", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 6: Enzyme and substrate concentration; enzymes at work in industry", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-6/", "max": 23, "sort": 16, "msort": 110, "csort": 37, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 3, "n": 3, "ans": ["Rate increases", "Rate stays the same", "Rate increases"], "tip": "Are the active sites already full?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["increase", "rise", "goes up"], ["more collisions", "more substrate", "more complexes", "collide"], ["level", "plateau", "saturated", "all active sites", "limiting"]], "tips": ["Rises, then?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 4, "pts": [["little lactase", "no lactase", "not enough lactase", "lack lactase"], ["bacteria", "ferment", "large intestine", "gas"], ["lactase is added", "add lactase", "lactase"], ["glucose", "galactose", "broken down", "already digested"]], "tips": ["Missing enzyme; who eats the lactose; factory solution."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Catalase", "Pectinase", "Protease", "Lipase", "Lactase"], "tip": "Match the substrate."}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 2, "pts": [["optimum", "protease", "lipase", "enzymes work"], ["denatur", "active site", "too hot"]], "tips": ["Enzymes and temperature."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 3, "pts": [["increase", "more liver", "proportional", "doubles"], ["23.5"], ["more enzyme", "more catalase", "more active sites"]], "tips": ["Plot in your head: does it double?"]}, {"kind": "text", "id": "q5_1", "q": "Q8", "max": 3, "pts": [["low temperature", "energy", "cheap", "save"], ["specific", "no unwanted", "pure", "reused", "biodegrad", "natural"], ["denatur", "expensive", "allerg", "pH", "conditions", "contamina"]], "tips": ["Energy, specificity; but…"]}]}, "models": {"1": [["Q1", "(a) More cashiers (enzymes) serve more customers per minute, so the queue moves faster. (b) More customers (substrate) cannot be served faster once every cashier is busy: the rate levels off. This is like enzymes and substrates."], ["Q2", "More enzyme with plenty of substrate: faster. More substrate at low concentration: faster. More substrate when saturated: no change."]], "2": [["Q3", "At first the rate increases as substrate concentration increases [1], because there are more collisions between substrate and active sites [1]; then the rate levels off, because all the active sites are occupied (saturated) and enzyme concentration becomes limiting [1]."]], "3": [["Q4", "They make too little lactase [1], so undigested lactose reaches the large intestine, where bacteria ferment it, producing gas and cramps [1]; in lactose-free milk lactase is added at the factory [1], so the lactose is already broken down into glucose and galactose, which are absorbed normally [1]."]], "4": [["Q5", "H₂O₂: catalase. Pectin: pectinase. Blood (protein): protease. Oil (fat): lipase. Lactose: lactase."], ["Q6", "The protease and lipase enzymes work best near their optimum of about 40 °C [1]; at 90 °C they are denatured, so their active sites no longer fit the stains [1]."]], "5": [["Q7", "As the mass of liver increases, the volume of oxygen increases roughly in proportion [1]; at 2.0 g: 47 ÷ 2.0 = 23.5 cm³ per gram [1]; more liver contains more catalase, so there are more active sites to break down hydrogen peroxide [1]."], ["Q8", "Enzymes work at low temperatures, so factories save energy and money [1]; they are specific, so they make pure products without unwanted by-products, and they can be reused [1]; however, they are easily denatured by heat or the wrong pH, and some people are allergic to enzyme powders [1]."]], "6": [["Exit ticket", "Lactase; glucose and galactose."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_0": "Q4", "q4_1": "Q6", "q5_0": "Q7", "q5_1": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "2b2427e4-fa17-5108-8e7b-f68983c867a0", "ext": "G9-BIO-DCR-L7", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 7: Hormones and blood sugar: insulin, glucagon and diabetes", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-7/", "max": 27, "sort": 17, "msort": 111, "csort": 38, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["Blood glucose rises", "Blood glucose falls", "Blood glucose rises", "Blood glucose falls"], "tip": "Food and glucagon raise; exercise and insulin lower."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 4, "pts": [["rises", "increase", "high"], ["pancreas", "detect"], ["insulin"], ["glycogen", "take up", "liver", "cells absorb"]], "tips": ["Detect, hormone, effect."]}, {"kind": "choice", "id": "q2_1", "q": "Q4", "max": 4, "n": 4, "ans": ["Insulin", "Glucagon", "Insulin", "Glucagon"], "tip": "In-sulin puts glucose in; glucagon: glucose gone."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 6, "n": 6, "ans": ["Type 1", "Type 2", "Type 2", "Type 1", "Type 1", "Type 2"], "tip": "Missing insulin, or insulin not working?"}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["no insulin", "little insulin", "does not make", "cannot make", "destroy"], ["resist", "do not respond", "don't respond", "not respond"]], "tips": ["Supply or response?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["higher", "rises more", "14", "more"], ["stays high", "does not fall", "still 12", "slower", "not return"], ["insulin", "no insulin", "resist", "not respond"]], "tips": ["Peak, return, reason."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 4, "pts": [["exercise", "walk", "cycle", "sport", "pe", "active"], ["sugar tax", "diet", "whole", "vegetables", "label", "education", "school meals"], ["weight", "obesity", "respond to insulin", "insulin", "glucose"], ["cost", "afford", "habit", "culture", "difficult", "roads", "time"]], "tips": ["Two actions, how they help, one difficulty."]}]}, "models": {"1": [["Q1", "It rises after each meal as glucose is absorbed, falls between meals as cells use glucose, and falls during the football match as muscles respire. It always returns to about the same level because hormones control it."], ["Q2", "Eating and glucagon raise it; exercise and insulin lower it."]], "2": [["Q3", "Blood glucose rises after the meal [1]; the pancreas detects the rise [1] and releases insulin [1]; insulin makes body cells take up glucose and the liver convert it to glycogen, so the level falls [1]."], ["Q4", "High glucose and uptake: insulin. Low glucose and glycogen breakdown: glucagon."]], "3": [["Q5", "No insulin, childhood, injections: type 1. Resistance, obesity, lifestyle: type 2."], ["Q6", "In type 1 the pancreas makes little or no insulin because its insulin-making cells are destroyed [1]; in type 2 the body cells stop responding properly to insulin (insulin resistance) [1]."]], "4": [["Q7", "The person with diabetes starts higher and rises much more (to 14 mmol/L compared with 8) [1]; their glucose stays high (12 after 2 hours) while the healthy person returns to 5 [1]; because they make too little insulin or their cells do not respond to it, glucose is not taken up from the blood [1]."]], "5": [["Q8", "Build safe walking and cycling paths and give daily PE in schools [1]; tax sugary drinks and teach healthy eating with whole maize flour and vegetables [1]; both reduce obesity, so body cells respond better to insulin [1]; a difficulty is that healthy food costs more and habits are hard to change [1]."]], "6": [["Exit ticket", "Insulin; it makes the liver convert glucose into glycogen."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "ba05bf5b-7766-51ae-a059-a3e4859e8c1f", "ext": "G9-BIO-DCR-L8", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 8: The heart and blood vessels", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-8/", "max": 30, "sort": 18, "msort": 112, "csort": 39, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Right atrium", "Right ventricle", "Left atrium", "Left ventricle", "Septum"], "tip": "Right = to lungs; left = to body."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["4th", "1st", "6th", "2nd", "5th", "3rd"], "tip": "Right side first, then lungs, then left side."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["more muscle", "thicker muscle", "stronger", "higher pressure", "contract harder"], ["whole body", "all round the body", "further", "body", "not just lungs"]], "tips": ["How far does each side pump?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 2, "pts": [["backflow", "backwards", "one direction", "flowing back"], ["vein", "low pressure", "return", "heart"]], "tips": ["Which way must blood go?"]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["twice", "two"], ["lungs", "pulmonary"], ["pressure", "high pressure", "faster", "more oxygen"]], "tips": ["Two circuits."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 6, "n": 6, "ans": ["Capillary", "Vein", "Artery", "Vein", "Capillary", "Artery"], "tip": "Structure fits pressure and job."}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 2, "pts": [["one cell", "thin"], ["diffus", "exchange", "short distance", "oxygen", "glucose"]], "tips": ["Thin wall → ?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 4, "pts": [["narrow", "block", "fatty", "plaque"], ["oxygen", "heart muscle", "cannot", "dies", "less blood"], ["exercise", "active", "walk"], ["smoking", "fat", "salt", "diet", "weight", "vegetables"]], "tips": ["Coronary → muscle → oxygen."]}]}, "models": {"1": [["Q1", "A resting pulse is about 60–80 beats per minute; after exercise it rises (e.g. to 120). The muscles respire faster and need more oxygen and glucose, and must get rid of more carbon dioxide, so the heart pumps faster."], ["Q2", "Right atrium receives from the body; right ventricle pumps to the lungs; left atrium receives from the lungs; left ventricle pumps to the body; septum separates."]], "2": [["Q3", "Vena cava → right atrium → right ventricle → lungs → left ventricle (via left atrium) → aorta."], ["Q4", "The left ventricle has more muscle so it can contract with more force and produce a higher pressure [1], because it pumps blood all round the body, while the right ventricle only pumps to the nearby lungs [1]."]], "3": [["Q5", "Valves prevent blood flowing backwards, keeping it moving in one direction [1]; in veins, where pressure is low, valves stop blood flowing back away from the heart [1]."], ["Q6", "Blood passes through the heart twice in each complete circuit of the body [1]: once through the lungs (pulmonary circulation) and once round the body (systemic circulation) [1]; this lets the heart pump blood to the body at high pressure, so oxygen is delivered quickly [1]."]], "4": [["Q7", "One cell thick, exchange: capillary. Valves, low pressure: vein. Thick elastic wall, pulse: artery."], ["Q8", "Its wall is only one cell thick [1], so oxygen and glucose can diffuse quickly over a short distance into body cells, and carbon dioxide out [1]."]], "5": [["Q9", "Fatty deposits narrow or block the coronary arteries [1], so less blood reaches the heart muscle, which is starved of oxygen and dies (a heart attack) [1]; regular exercise [1] and not smoking, with a diet low in saturated fat and salt, lower the risk [1]."]], "6": [["Exit ticket", "The aorta; the left ventricle."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_0": "Q5", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "bf0e87f2-76ca-5925-b347-d853a7a34f52", "ext": "G9-BIO-DCR-L9", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 9: Blood: plasma, cells, platelets and blood groups", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-9/", "max": 28, "sort": 19, "msort": 113, "csort": 40, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Red blood cells", "Platelets", "Plasma", "White blood cells", "White blood cells"], "tip": "Transport, oxygen, defence, clotting."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["haemoglobin"], ["no nucleus", "more room", "more space"], ["biconcave", "surface area", "flexible", "squeeze", "small"]], "tips": ["Contents, missing part, shape."]}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["haemoglobin", "anaemia"], ["less oxygen", "oxygen", "respiration", "energy"]], "tips": ["Iron → haemoglobin → oxygen."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Phagocyte", "Lymphocyte", "Platelet", "Phagocyte", "Platelet"], "tip": "Eat, mark or plug."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["bleeding", "blood loss", "lose blood"], ["pathogen", "bacteria", "infection", "germs"]], "tips": ["Two reasons."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 5, "n": 5, "ans": ["Safe", "Not safe", "Safe", "Not safe", "Safe"], "tip": "Does the donor's blood carry an antigen the patient has antibodies against?"}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 2, "pts": [["no antigen", "no a or b", "neither antigen", "no a and b"], ["not attacked", "no agglutination", "no clumping", "antibodies", "anyone"]], "tips": ["What is on the surface of O red cells?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 4, "pts": [["fear", "myth", "needles", "not aware", "awareness", "funding", "weight", "age"], ["donor", "drive", "campaign", "education", "awareness", "mobile", "clubs"], ["fear", "myth", "funding", "storage", "few centres", "transport", "not aware"], ["drive", "campaign", "education", "awareness", "clubs", "social media", "rewards"]], "tips": ["Barriers, then solutions."]}]}, "models": {"1": [["Q1", "A large pale yellow layer of plasma on top (about 55%), a thin whitish layer of white blood cells and platelets, and a dark red layer of red blood cells at the bottom (about 45%)."], ["Q2", "Haemoglobin: red cells. Clotting: platelets. Dissolved substances: plasma. Engulfing and antibodies: white cells."]], "2": [["Q3", "They contain haemoglobin, which combines with oxygen [1]; they have no nucleus, leaving more room for haemoglobin [1]; their biconcave shape gives a large surface area for oxygen to diffuse in and out, and they are flexible enough to squeeze through capillaries [1]."], ["Q4", "Iron is needed to make haemoglobin, so they make less (anaemia) [1]; their blood carries less oxygen, so cells release less energy in respiration [1]."]], "3": [["Q5", "Engulfing, lobed nucleus: phagocyte. Antibodies: lymphocyte. Clotting, fragment: platelet."], ["Q6", "Clotting stops bleeding, preventing blood loss [1] and seals the wound so pathogens cannot enter [1]."]], "4": [["Q7", "O to A: safe. A to B: not safe (anti-A). B to AB: safe. AB to O: not safe. A to A: safe."], ["Q8", "Group O red blood cells have no A or B antigens [1], so the patient's antibodies do not attack them and no agglutination occurs [1]."]], "5": [["Q9", "Many people fear needles or believe myths about donating blood [1], and donation centres are few and poorly funded [1]; schools could hold blood donation drives for students over 16 and staff [1], and run awareness campaigns explaining that donating is safe and saves lives [1]."]], "6": [["Exit ticket", "Red blood cells carry oxygen; white blood cells defend against pathogens; platelets help blood to clot."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q2_1": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "8a012f6f-5427-55f0-a50d-9d9dd4d32a92", "ext": "G9-BIO-DCR-L10", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 10: Pathogens, immunity and vaccination", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-10/", "max": 28, "sort": 20, "msort": 114, "csort": 41, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["Bacterium", "Virus", "Protist", "Fungus", "Bacterium", "Virus"], "tip": "Cholera and TB are bacteria; malaria is Plasmodium."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 6, "n": 6, "ans": ["Contaminated water or food", "Air droplets", "Body fluids", "Vector (mosquito)", "Contaminated water or food", "Air droplets"], "tip": "Think about where outbreaks happen."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["clean water", "boil", "chlorine", "treat"], ["toilets", "latrines", "sanitation", "hand", "wash", "sewage"]], "tips": ["Water and waste."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 3, "pts": [["antigen", "recognise"], ["antibod"], ["specific", "stick", "bind", "destroy", "clump", "phagocyte"]], "tips": ["Antigen → antibody → destroy."]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["memory cells", "memory"], ["faster", "quickly", "more antibodies", "secondary", "before symptoms"]], "tips": ["What is left after the first infection?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 4, "pts": [["dead", "weakened", "inactive", "harmless", "antigen"], ["lymphocyte", "antibod"], ["memory"], ["faster", "quickly", "secondary", "destroy", "before"]], "tips": ["What is in it, what the body makes, what happens later."]}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 2, "pts": [["herd immunity", "cannot spread", "fewer hosts", "spread"], ["babies", "cannot be vaccinated", "unvaccinated", "protect", "weak", "ill"]], "tips": ["Who else is protected?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 3, "pts": [["community health", "mobile clinic", "outreach", "chiefs", "sms", "reminder", "education", "religious leaders", "school"], ["difficult", "cost", "distance", "trust", "rumour", "myth", "cold chain", "staff"], ["i think", "overall", "conclusion", "should", "because"]], "tips": ["Benefit, difficulty, conclusion."]}]}, "models": {"1": [["Q1", "It was probably spread by droplets from someone coughing or sneezing, or on hands. After recovering, the body had antibodies and memory cells against that virus, so it could destroy it quickly if met again."], ["Q2", "Cholera, TB: bacteria. Measles, HIV: viruses. Malaria: protist. Athlete's foot: fungus."]], "2": [["Q3", "Cholera and typhoid: water and food. TB and measles: air. HIV: body fluids. Malaria: mosquitoes."], ["Q4", "Provide clean, treated water or boil drinking water [1]; build toilets and promote handwashing with soap so faeces do not contaminate water [1]."]], "3": [["Q5", "Lymphocytes recognise the antigens on the pathogen [1] and make antibodies [1] that are specific to those antigens; the antibodies bind to the pathogen and destroy it or mark it for phagocytes [1]."], ["Q6", "After the first infection, memory cells remain [1]; on a second infection they make antibodies faster and in larger amounts, destroying the virus before symptoms develop [1]."]], "4": [["Q7", "The vaccine contains dead or weakened polio virus with its antigens, which cannot cause disease [1]; lymphocytes make antibodies against the antigens [1] and memory cells are formed [1]; if the child later meets the real virus, the memory cells quickly make lots of antibodies and destroy it before the child becomes ill [1]."], ["Q8", "If most people are immune, the pathogen cannot spread from person to person (herd immunity) [1], which protects babies and people who cannot be vaccinated [1]."]], "5": [["Q9", "Community health volunteers could visit homes, remind parents by SMS and answer fears, bringing vaccines closer and building trust [1]; a difficulty is keeping vaccines cold far from towns and paying enough trained staff [1]; overall I think it is worth it because preventing measles outbreaks saves many children's lives [1]."]], "6": [["Exit ticket", "A vaccine contains harmless antigens, so lymphocytes make antibodies and memory cells. If the real pathogen enters later, memory cells quickly make antibodies and destroy it."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_0": "Q5", "q3_1": "Q6", "q4_0": "Q7", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "ad152b59-0eef-52f3-9a3d-348ef5979471", "ext": "G9-BIO-DCR-L11", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 11: Cellular respiration and ATP", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-11/", "max": 30, "sort": 21, "msort": 115, "csort": 42, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 5, "n": 5, "ans": ["Respiration", "Breathing", "Respiration", "Breathing", "Respiration"], "tip": "Physical movement of air, or a chemical reaction?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 3, "pts": [["glucose oxygen", "glucose and oxygen"], ["carbon dioxide water", "carbon dioxide and water"], ["c6h12o6", "6h2o", "6co2", "6o2"]], "tips": ["Reactants → products."]}, {"kind": "choice", "id": "q2_1", "q": "Q4", "max": 5, "n": 5, "ans": ["Anaerobic (muscle)", "Anaerobic (yeast)", "Aerobic", "Anaerobic (yeast)", "Anaerobic (muscle)"], "tip": "Oxygen? Which organism?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 3, "pts": [["adenosine triphosphate", "three phosphate", "phosphate"], ["respiration", "made", "adp"], ["release", "broken down", "spend", "where needed", "used for", "small amounts"]], "tips": ["Made, then spent."]}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["oxygen"], ["lactic acid", "less energy", "more energy", "atp", "carbon dioxide"]], "tips": ["Oxygen, products, energy."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 5, "n": 5, "ans": ["Movement", "Sensitivity", "Growth", "Reproduction", "Nutrition"], "tip": "MRS GREN."}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 3, "pts": [["movement", "muscle", "contract"], ["growth", "protein", "new cells", "repair", "divide"], ["sensitiv", "nerve", "excret", "kidney", "active transport", "nutrition", "reproduc", "warm"]], "tips": ["Energy for…"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 4, "pts": [["increase", "rise", "up to 40", "more bubbles"], ["decrease", "fall", "fell", "stopped", "above 40", "no bubbles"], ["enzyme", "denatur", "optimum"], ["sugar", "volume", "concentration", "mass of yeast", "same yeast", "time"]], "tips": ["Up, down, why, control."]}]}, "models": {"1": [["Q1", "Cells are respiring all the time and need a constant supply of oxygen; carbon dioxide from respiration builds up in the blood. The brain detects it and makes you breathe again."], ["Q2", "Air movement with muscles: breathing. Energy from glucose in cells and mitochondria: respiration."]], "2": [["Q3", "Word equation: glucose + oxygen [1] → carbon dioxide + water [1]; chemical equation: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O [1]."], ["Q4", "Lactic acid and cramp: muscle. Ethanol, CO₂ and bread: yeast. Oxygen and most energy: aerobic."]], "3": [["Q5", "ATP (adenosine triphosphate) has three phosphate groups [1]; energy from respiration is used to make ATP from ADP and phosphate [1]; ATP is broken down to release energy in small, usable amounts wherever the cell needs it, like spending money [1]."], ["Q6", "Aerobic respiration needs oxygen but anaerobic does not [1]; aerobic produces carbon dioxide and water and much more energy (ATP), while anaerobic produces lactic acid and little energy [1]."]], "4": [["Q7", "Contracting: movement. Nerve impulse: sensitivity. Building proteins: growth. Making gametes: reproduction. Absorbing glucose: nutrition."], ["Q8", "Respiration releases energy as ATP for movement, by muscle contraction [1]; for growth, by building proteins and new cells [1]; and for sensitivity, by sending nerve impulses (also active transport in nutrition and excretion) [1]."]], "5": [["Q9", "The rate of bubbling increased from 6 to 25 per minute between 20 and 40 °C [1], then fell and stopped at 60 °C [1]; respiration is controlled by enzymes: they work faster up to the optimum, then denature at high temperatures [1]; the concentration and volume of sugar solution and mass of yeast must be kept the same [1]."]], "6": [["Exit ticket", "Glucose + oxygen → carbon dioxide + water; adenosine triphosphate."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q3_0": "Q5", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}, {"id": "b4681e9c-1fed-5858-8e9a-9b6d82745d5c", "ext": "G9-BIO-DCR-L12", "title": "Biology · Digestion, enzymes, circulation and respiration · Lesson 12: Integration: the digestive and cardiovascular systems working together", "summary": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "url": "/g9-bio-dcr-12/", "max": 22, "sort": 22, "msort": 116, "csort": 43, "spec": {"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 6, "n": 6, "ans": ["4th", "1st", "6th", "2nd", "5th", "3rd"], "tip": "Digest, absorb, liver, heart, cell, mitochondrion."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 4, "pts": [["digest", "amylase", "starch"], ["absorb", "villi", "villus", "small intestine"], ["blood", "heart", "pump", "artery", "transport"], ["capillar", "diffus", "muscle cell"]], "tips": ["Digest → absorb → transport → deliver."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Digestive system", "Respiratory system", "Cardiovascular system", "Respiratory system", "Excretory system (kidneys)"], "tip": "Where does it come from or go?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["haemoglobin", "red blood cells", "less oxygen"], ["breath", "breathing rate", "heart rate", "breathless"], ["muscle", "respir", "atp", "energy", "tired", "weak"]], "tips": ["Less oxygen carried → ?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 4, "pts": [["diet", "activity", "exercise", "smoking", "alcohol"], ["digest", "liver", "gut", "fibre", "stomach"], ["heart", "arteries", "blood", "coronary", "lungs", "alveoli"], ["depend", "interdependent", "affects the other", "together", "linked", "all systems"]], "tips": ["One factor, two systems, link."]}]}, "models": {"1": [["Q1", "Digestive (digests and absorbs the food), cardiovascular (carries glucose and oxygen), respiratory (takes in oxygen, removes CO₂), muscular and skeletal (movement), nervous (controls muscles and heart rate), endocrine (insulin controls glucose)."], ["Q2", "Digested → absorbed → liver → heart and arteries → into the cell → respired."]], "2": [["Q3", "Starch is digested to glucose by amylase in the small intestine [1]; glucose is absorbed into the blood through the villi [1]; the heart pumps the blood through arteries to the muscle [1]; in the capillaries, glucose diffuses into the muscle cell [1]."]], "3": [["Q4", "Glucose: digestive. Oxygen and CO₂: respiratory. Transport: cardiovascular. Urea: kidneys."]], "4": [["Q5", "With fewer red blood cells and less haemoglobin, the blood carries less oxygen [1]; the child breathes faster and the heart beats faster to compensate, so they are breathless [1]; muscle cells get less oxygen for aerobic respiration, make less ATP and the child feels weak and tired [1]."]], "5": [["Q6", "Smoking [1] damages the alveoli and cilia of the respiratory system and narrows the coronary arteries of the cardiovascular system [1]; with less oxygen absorbed and delivered, cells in the gut and liver respire less efficiently [1]; this shows the systems are interdependent: damage to one reduces the function of the others [1]."]], "6": [["Exit ticket", "The hepatic portal vein; the villi of the small intestine (capillaries in the villi)."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}}], "quizzes": [{"id": "40d9916e-e1c1-5d95-9ac9-a973d1f033c8", "title": "Grade 9 · Biology · Digestion, enzymes, circulation and respiration · Lesson 1: The digestive system: structure and function · Criteria A and D exam-style questions", "instr": "Exam-style questions for the lesson \"The digestive system: structure and function\" (MYP 4, Grade 9 Biology). Criterion A: Knowing and understanding. Criterion D: Reflecting on the impacts of science. 12 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "7afe4ef3-ee81-5cee-acf5-50414fee7b9b", "title": "Grade 9 · Biology · Digestion, enzymes, circulation and respiration · Lesson 2: Digestion, absorption and egestion in detail · Criteria A, B and D exam-style questions", "instr": "Exam-style questions for the lesson \"Digestion, absorption an