rk."}, {"id": "c9c20e79-4b63-520b-8d9c-ddc9f9ce01a4", "title": "Grade 9 · Biology · Digestion, enzymes, circulation and respiration · Lesson 9: Blood: plasma, cells, platelets and blood groups · Criteria A and D exam-style questions", "instr": "Exam-style questions for the lesson \"Blood: plasma, cells, platelets and blood groups\" (MYP 4, Grade 9 Biology). Criterion A: Knowing and understanding. Criterion D: Reflecting on the impacts of science. 11 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "f0859644-815e-5903-9c0c-a976a64da3e2", "title": "Grade 9 · Biology · Digestion, enzymes, circulation and respiration · Lesson 10: Pathogens, immunity and vaccination · Criteria A and D exam-style questions", "instr": "Exam-style questions for the lesson \"Pathogens, immunity and vaccination\" (MYP 4, Grade 9 Biology). Criterion A: Knowing and understanding. Criterion D: Reflecting on the impacts of science. 9 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "06fe14a5-8949-54c1-82e9-33aa7a30f99c", "title": "Grade 9 · Biology · Digestion, enzymes, circulation and respiration · Lesson 11: Cellular respiration and ATP · Criteria A, B and C exam-style questions", "instr": "Exam-style questions for the lesson \"Cellular respiration and ATP\" (MYP 4, Grade 9 Biology). Criterion A: Knowing and understanding. Criterion C: Processing and evaluating. 10 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}, {"id": "0324e067-4cf8-5d82-8948-f990a3218b39", "title": "Grade 9 · Biology · Digestion, enzymes, circulation and respiration · Lesson 12: Integration: the digestive and cardiovascular systems working together · Criteria A and D exam-style questions", "instr": "Exam-style questions for the lesson \"Integration: the digestive and cardiovascular systems working together\" (MYP 4, Grade 9 Biology). Criterion A: Knowing and understanding. Criterion D: Reflecting on the impacts of science. 11 marks. Do the lesson first. Written answers are marked against the mark scheme and you get detailed feedback; your teacher checks every mark."}], "questions": [{"id": "b529fda8-9fcd-596a-99f9-3dd9bbc2ccc2", "quiz": "40d9916e-e1c1-5d95-9ac9-a973d1f033c8", "pos": 1, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nName the organ.\nAbsorbs water from undigested food", "options": ["Stomach", "Small intestine", "Large intestine", "Liver", "Pancreas"], "marks": 1, "section": "Criterion A", "correct": 2, "model": "Large intestine; liver; stomach; small intestine; pancreas.", "points": null}, {"id": "a6bb02b0-0af7-5b46-a1ab-75ee2f31334d", "quiz": "40d9916e-e1c1-5d95-9ac9-a973d1f033c8", "pos": 2, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nName the organ.\nMakes bile", "options": ["Stomach", "Small intestine", "Large intestine", "Liver", "Pancreas"], "marks": 1, "section": "Criterion A", "correct": 3, "model": "Large intestine; liver; stomach; small intestine; pancreas.", "points": null}, {"id": "69c54114-516e-57d4-98b0-c2603394b77f", "quiz": "40d9916e-e1c1-5d95-9ac9-a973d1f033c8", "pos": 3, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nName the organ.\nContains acid that kills bacteria", "options": ["Stomach", "Small intestine", "Large intestine", "Liver", "Pancreas"], "marks": 1, "section": "Criterion A", "correct": 0, "model": "Large intestine; liver; stomach; small intestine; pancreas.", "points": null}, {"id": "083c7cfd-2591-55eb-b73e-d07c6ba76ddb", "quiz": "40d9916e-e1c1-5d95-9ac9-a973d1f033c8", "pos": 4, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nName the organ.\nWhere digested food is absorbed into the blood", "options": ["Stomach", "Small intestine", "Large intestine", "Liver", "Pancreas"], "marks": 1, "section": "Criterion A", "correct": 1, "model": "Large intestine; liver; stomach; small intestine; pancreas.", "points": null}, {"id": "fb683033-4f45-5497-ac00-f9ef4d61af34", "quiz": "40d9916e-e1c1-5d95-9ac9-a973d1f033c8", "pos": 5, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nName the organ.\nMakes amylase, protease and lipase", "options": ["Stomach", "Small intestine", "Large intestine", "Liver", "Pancreas"], "marks": 1, "section": "Criterion A", "correct": 4, "model": "Large intestine; liver; stomach; small intestine; pancreas.", "points": null}, {"id": "fe5e8188-2522-5fba-988a-fb75d16370c8", "quiz": "40d9916e-e1c1-5d95-9ac9-a973d1f033c8", "pos": 6, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nOutline the processes of digestion, absorption and egestion.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "Digestion breaks large insoluble molecules into small soluble ones [1]; absorption is the movement of these small molecules through the wall of the small intestine into the blood [1]; egestion removes undigested food as faeces through the anus [1].", "points": [{"text": "Digestion breaks large insoluble molecules into small soluble ones", "any": ["break", "large", "small", "soluble", "enzymes"], "all": [], "marks": 1}, {"text": "Absorption is the movement of these small molecules through the wall of the small intestine into the blood", "any": ["into the blood", "pass into", "cross", "through the wall", "blood"], "all": [], "marks": 1}, {"text": "Egestion removes undigested food as faeces through the anus", "any": ["undigested", "faeces", "anus", "remov"], "all": [], "marks": 1}]}, {"id": "a5126020-5dd3-5477-b3c8-c9a4beabc13d", "quiz": "40d9916e-e1c1-5d95-9ac9-a973d1f033c8", "pos": 7, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDescribe how food is moved along the oesophagus.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "By peristalsis: the muscles in the wall contract [1] in waves behind the food, squeezing it along [1].", "points": [{"text": "By peristalsis: the muscles in the wall contract", "any": ["peristalsis", "muscle", "contract"], "all": [], "marks": 1}, {"text": "In waves behind the food, squeezing it along", "any": ["wave", "push", "squeez", "behind"], "all": [], "marks": 1}]}, {"id": "3076feb2-3c36-543b-a898-eabf5dc6b592", "quiz": "40d9916e-e1c1-5d95-9ac9-a973d1f033c8", "pos": 8, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nSuggest why a person whose large intestine is damaged by cholera can become dangerously dehydrated.", "options": [], "marks": 2, "section": "Criterion D", "correct": null, "model": "The large intestine cannot absorb water [1], so large amounts of water are lost in watery faeces (diarrhoea) [1].", "points": [{"text": "The large intestine cannot absorb water", "any": ["water", "not absorbed", "cannot absorb", "absorb"], "all": [], "marks": 1}, {"text": "Large amounts of water are lost in watery faeces (diarrhoea)", "any": ["diarrhoea", "lost", "faeces", "watery", "loses"], "all": [], "marks": 1}]}, {"id": "93b1d3b8-a442-5876-996e-464bf7aab139", "quiz": "7afe4ef3-ee81-5cee-acf5-50414fee7b9b", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDistinguish between mechanical and chemical digestion, with one example of each.", "options": [], "marks": 4, "section": "Criterion A", "correct": null, "model": "Mechanical digestion breaks food physically into smaller pieces [1], e.g. chewing by teeth [1]; chemical digestion uses enzymes to break large molecules into small ones [1], e.g. amylase digesting starch [1].", "points": [{"text": "Mechanical digestion breaks food physically into smaller pieces", "any": ["physical", "smaller pieces", "break up"], "all": [], "marks": 1}, {"text": "E.g. chewing by teeth", "any": ["chew", "teeth", "churn", "bile", "emulsif"], "all": [], "marks": 1}, {"text": "Chemical digestion uses enzymes to break large molecules into small ones", "any": ["enzyme", "molecules", "bonds"], "all": [], "marks": 1}, {"text": "E.g. amylase digesting starch", "any": ["amylase", "protease", "lipase", "pepsin"], "all": [], "marks": 1}]}, {"id": "fa1bbc9e-4cc8-5d2b-9495-e6c5683e046c", "quiz": "7afe4ef3-ee81-5cee-acf5-50414fee7b9b", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDescribe how the structure of a villus is adapted for absorption.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "Villi and microvilli give a large surface area [1]; a wall one cell thick gives a short diffusion distance [1]; a good blood supply (capillaries) and a lacteal carry absorbed food away [1].", "points": [{"text": "Villi and microvilli give a large surface area", "any": ["surface area", "microvilli", "folds"], "all": [], "marks": 1}, {"text": "A wall one cell thick gives a short diffusion distance", "any": ["thin", "one cell"], "all": [], "marks": 1}, {"text": "A good blood supply (capillaries) and a lacteal carry absorbed food away", "any": ["capillar", "blood supply", "lacteal"], "all": [], "marks": 1}]}, {"id": "fb6e86ba-1f9d-5805-aaa6-f80498a7a986", "quiz": "7afe4ef3-ee81-5cee-acf5-50414fee7b9b", "pos": 3, "kind": "short", "prompt": "[Criterion B: Inquiring and designing]\nIn a Visking tubing experiment, starch and amylase were placed inside the tubing in water. Explain why sugar but not starch was found in the water after 30 minutes.", "options": [], "marks": 2, "section": "Criterion B", "correct": null, "model": "Amylase digested the starch into sugar [1]; sugar molecules are small enough to pass through the pores in the tubing but starch molecules are too large [1].", "points": [{"text": "Amylase digested the starch into sugar", "any": ["digest", "amylase", "broke", "broken"], "all": [], "marks": 1}, {"text": "Sugar molecules are small enough to pass through the pores in the tubing but starch molecules are too large", "any": ["small", "large", "pass through", "holes", "pores"], "all": [], "marks": 1}]}, {"id": "63ce23af-9c8c-57a1-a191-0b408a696c25", "quiz": "7afe4ef3-ee81-5cee-acf5-50414fee7b9b", "pos": 4, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nOral rehydration solution (ORS) is made with clean water, salt and a little sugar. Explain why ORS saves the lives of children with diarrhoea, and why clean water and toilets prevent diarrhoea.", "options": [], "marks": 3, "section": "Criterion D", "correct": null, "model": "ORS replaces the water lost in diarrhoea [1] and the salts, with the sugar helping the intestine absorb them [1]; clean water and toilets stop pathogens such as cholera bacteria from faeces getting into drinking water [1].", "points": [{"text": "ORS replaces the water lost in diarrhoea", "any": ["water", "rehydrat", "replace"], "all": [], "marks": 1}, {"text": "The salts, with the sugar helping the intestine absorb them", "any": ["salt", "sugar", "absorb", "minerals"], "all": [], "marks": 1}, {"text": "Clean water and toilets stop pathogens such as cholera bacteria from faeces getting into drinking water", "any": ["pathogen", "bacteria", "cholera", "germs", "contaminat", "faeces"], "all": [], "marks": 1}]}, {"id": "0c3d2107-08d3-51fb-b3b8-91cd96048106", "quiz": "ef201cb3-c0bc-5d28-8a3b-d8631d4607f6", "pos": 1, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nMatch the enzyme to its product.\nAmylase", "options": ["Maltose", "Amino acids", "Fatty acids and glycerol"], "marks": 1, "section": "Criterion A", "correct": 0, "model": "Amylase → maltose; protease → amino acids; lipase → fatty acids and glycerol.", "points": null}, {"id": "b361452d-c399-568d-aae2-3f621110e54b", "quiz": "ef201cb3-c0bc-5d28-8a3b-d8631d4607f6", "pos": 2, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nMatch the enzyme to its product.\nProtease", "options": ["Maltose", "Amino acids", "Fatty acids and glycerol"], "marks": 1, "section": "Criterion A", "correct": 1, "model": "Amylase → maltose; protease → amino acids; lipase → fatty acids and glycerol.", "points": null}, {"id": "738ddd9d-7591-59bc-b14b-8212728dff9c", "quiz": "ef201cb3-c0bc-5d28-8a3b-d8631d4607f6", "pos": 3, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nMatch the enzyme to its product.\nLipase", "options": ["Maltose", "Amino acids", "Fatty acids and glycerol"], "marks": 1, "section": "Criterion A", "correct": 2, "model": "Amylase → maltose; protease → amino acids; lipase → fatty acids and glycerol.", "points": null}, {"id": "74891c6c-0ac4-5bae-ad7e-1fd6dfecc270", "quiz": "ef201cb3-c0bc-5d28-8a3b-d8631d4607f6", "pos": 4, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nState where bile is made and stored, and explain why it is not an enzyme.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "Bile is made in the liver [1] and stored in the gall bladder [1]; it is not an enzyme because it does not catalyse a chemical reaction: it only emulsifies fat physically [1].", "points": [{"text": "Bile is made in the liver", "any": ["liver"], "all": [], "marks": 1}, {"text": "Stored in the gall bladder", "any": ["gall bladder"], "all": [], "marks": 1}, {"text": "It is not an enzyme because it does not catalyse a chemical reaction: it only emulsifies fat physically", "any": ["not a protein", "does not break bonds", "does not catalyse", "physical", "no chemical", "emulsif"], "all": [], "marks": 1}]}, {"id": "a030b77e-08f8-5a06-a971-b41b1561a9f5", "quiz": "ef201cb3-c0bc-5d28-8a3b-d8631d4607f6", "pos": 5, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nExplain why chewing food well helps digestion.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "Chewing breaks food into smaller pieces with a larger surface area [1], so enzymes can act on more of it at once and digestion is faster [1].", "points": [{"text": "Chewing breaks food into smaller pieces with a larger surface area", "any": ["surface area", "smaller pieces"], "all": [], "marks": 1}, {"text": "Enzymes can act on more of it at once and digestion is faster", "any": ["enzyme", "faster", "amylase", "more"], "all": [], "marks": 1}]}, {"id": "6fa37293-756e-594c-8afd-bbec12f0b047", "quiz": "ef201cb3-c0bc-5d28-8a3b-d8631d4607f6", "pos": 6, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nStarch was digested by amylase. With whole bread, 2.4 g of sugar was produced in 10 minutes; with crumbled bread, 6.0 g. Calculate the rate of sugar production in each case and explain the difference.", "options": [], "marks": 3, "section": "Criterion C", "correct": null, "model": "Whole bread: 2.4 ÷ 10 = 0.24 g per minute [1]; crumbled: 6.0 ÷ 10 = 0.6 g per minute [1]; crumbled bread has a larger surface area, so amylase digests the starch faster [1].", "points": [{"text": "Whole bread: 2.4 ÷ 10 = 0.24 g per minute", "any": ["0.24"], "all": [], "marks": 1}, {"text": "Crumbled: 6.0 ÷ 10 = 0.6 g per minute", "any": ["0.6", "0.60"], "all": [], "marks": 1}, {"text": "Crumbled bread has a larger surface area, so amylase digests the starch faster", "any": ["surface area", "smaller", "crumbl"], "all": [], "marks": 1}]}, {"id": "ea16a7d9-f4c9-5e33-8151-67cb90b8fd87", "quiz": "8ce53a2a-bd88-55ea-8d31-65e0f1b4612e", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nState four functions of the liver.", "options": [], "marks": 4, "section": "Criterion A", "correct": null, "model": "Stores glucose as glycogen [1]; makes bile [1]; deamination of excess amino acids to form urea [1]; detoxification of alcohol and drugs (or storing vitamins and iron) [1].", "points": [{"text": "Stores glucose as glycogen", "any": ["glycogen", "glucose"], "all": [], "marks": 1}, {"text": "Makes bile", "any": ["bile"], "all": [], "marks": 1}, {"text": "Deamination of excess amino acids to form urea", "any": ["deamination", "urea", "amino acids"], "all": [], "marks": 1}, {"text": "Detoxification of alcohol and drugs (or storing vitamins and iron)", "any": ["detox", "alcohol", "poison", "vitamin", "iron", "heat", "plasma protein", "red blood cells"], "all": [], "marks": 1}]}, {"id": "e9309e65-3038-5639-8b80-ce6eb066eb82", "quiz": "8ce53a2a-bd88-55ea-8d31-65e0f1b4612e", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nExplain why the hepatic portal vein is important.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "It carries blood rich in absorbed food from the intestines [1] directly to the liver, so the liver can process it first [1].", "points": [{"text": "It carries blood rich in absorbed food from the intestines", "any": ["intestine", "gut", "absorbed", "digested"], "all": [], "marks": 1}, {"text": "Directly to the liver, so the liver can process it first", "any": ["liver", "process", "first"], "all": [], "marks": 1}]}, {"id": "36fed229-e343-5a62-aa66-0cf94a2b602c", "quiz": "8ce53a2a-bd88-55ea-8d31-65e0f1b4612e", "pos": 3, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nExplain why a person with liver failure may develop jaundice.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "The liver cannot remove bilirubin from old red blood cells [1], so it builds up in the blood and turns the skin and eyes yellow [1].", "points": [{"text": "The liver cannot remove bilirubin from old red blood cells", "any": ["bilirubin", "bile", "red blood cells"], "all": [], "marks": 1}, {"text": "It builds up in the blood and turns the skin and eyes yellow", "any": ["build up", "yellow", "not removed", "accumulat"], "all": [], "marks": 1}]}, {"id": "f51610a5-215e-50c5-ba9b-1686407b65cc", "quiz": "8ce53a2a-bd88-55ea-8d31-65e0f1b4612e", "pos": 4, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nHepatitis B vaccine is given to all babies in Kenya. Discuss why vaccinating babies against a liver disease is a good use of public health money.", "options": [], "marks": 3, "section": "Criterion D", "correct": null, "model": "The vaccine prevents infection by making babies immune [1]; hepatitis B caught in childhood often becomes lifelong and can lead to cirrhosis and liver cancer [1]; preventing it is much cheaper than treating liver failure and stops the virus spreading in the community [1].", "points": [{"text": "The vaccine prevents infection by making babies immune", "any": ["prevent", "protect", "immun"], "all": [], "marks": 1}, {"text": "Hepatitis B caught in childhood often becomes lifelong and can lead to cirrhosis and liver cancer", "any": ["cirrhosis", "liver cancer", "liver failure", "death", "lifelong", "chronic"], "all": [], "marks": 1}, {"text": "Preventing it is much cheaper than treating liver failure and stops the virus spreading in the community", "any": ["cheaper", "cost", "treatment", "expensive", "spread", "mother", "herd"], "all": [], "marks": 1}]}, {"id": "9fc2978c-a27d-59cc-a83e-aa1bc45dd53b", "quiz": "9716b74c-6dfb-5fc9-ac13-744189ad73dd", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDefine an enzyme and explain why enzymes are specific.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "An enzyme is a biological catalyst that speeds up reactions without being used up [1]; it is a protein [1]; its active site has a shape complementary to only one substrate, so it is specific [1].", "points": [{"text": "An enzyme is a biological catalyst that speeds up reactions without being used up", "any": ["catalyst", "speed up"], "all": [], "marks": 1}, {"text": "It is a protein", "any": ["protein", "biological"], "all": [], "marks": 1}, {"text": "Its active site has a shape complementary to only one substrate, so it is specific", "any": ["active site", "complementary", "one substrate", "shape"], "all": [], "marks": 1}]}, {"id": "6cc76716-dab8-5ced-9459-3707880a9bb6", "quiz": "9716b74c-6dfb-5fc9-ac13-744189ad73dd", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nExplain what is meant by denaturation.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "Denaturation is a permanent change in the shape of an enzyme's active site caused by high temperature or extreme pH [1], so the substrate no longer fits [1].", "points": [{"text": "Denaturation is a permanent change in the shape of an enzyme's active site caused by high temperature or extreme pH", "any": ["shape", "active site"], "all": [], "marks": 1}, {"text": "The substrate no longer fits", "any": ["substrate", "no longer fits", "cannot bind", "permanent", "heat", "ph"], "all": [], "marks": 1}]}, {"id": "abab7c55-1658-58f5-8b74-a46540ca010e", "quiz": "9716b74c-6dfb-5fc9-ac13-744189ad73dd", "pos": 3, "kind": "short", "prompt": "[Criterion B: Inquiring and designing]\nA student wants to find the optimum pH of amylase. Suggest the independent variable, how to change it, and two variables to control.", "options": [], "marks": 3, "section": "Criterion B", "correct": null, "model": "Independent variable: pH [1], changed using buffer solutions of pH 4, 5, 6, 7, 8 and 9 [1]; controls: the temperature (water bath at 37 °C) and the volume and concentration of starch and amylase [1].", "points": [{"text": "Independent variable: pH", "any": ["ph"], "all": [], "marks": 1}, {"text": "Changed using buffer solutions of pH 4, 5, 6, 7, 8 and 9", "any": ["buffer"], "all": [], "marks": 1}, {"text": "Controls: the temperature (water bath at 37 °C) and the volume and concentration of starch and amylase", "any": ["temperature", "volume", "concentration", "water bath"], "all": [], "marks": 1}]}, {"id": "ac6b05df-ca65-56c9-9e71-cd58bab5f475", "quiz": "9716b74c-6dfb-5fc9-ac13-744189ad73dd", "pos": 4, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nStarch digestion time by amylase: 20 °C 300 s; 30 °C 150 s; 40 °C 60 s; 50 °C 120 s; 60 °C no digestion after 600 s. Identify the optimum, calculate the rate at 40 °C as 1/time, and explain the result at 60 °C.", "options": [], "marks": 3, "section": "Criterion C", "correct": null, "model": "The optimum is about 40 °C [1]; rate = 1 ÷ 60 = 0.017 s⁻¹ [1]; at 60 °C the amylase was denatured, so its active site no longer fitted starch [1].", "points": [{"text": "The optimum is about 40 °C", "any": ["40"], "all": [], "marks": 1}, {"text": "Rate = 1 ÷ 60 = 0.017 s⁻¹", "any": ["0.017", "0.0167", "1/60", "1 ÷ 60"], "all": [], "marks": 1}, {"text": "At 60 °C the amylase was denatured, so its active site no longer fitted starch", "any": ["denatur", "active site"], "all": [], "marks": 1}]}, {"id": "d5cdae4e-771e-5688-90b0-acc8bfdf166f", "quiz": "c73c4125-4860-5b26-a6f2-7d1a8126bc92", "pos": 1, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nWhich enzyme catalyses the reaction?\nHydrogen peroxide → water + oxygen", "options": ["Lactase", "Catalase", "Protease", "Lipase"], "marks": 1, "section": "Criterion A", "correct": 1, "model": "Catalase; lactase; lipase; protease.", "points": null}, {"id": "e43b43e2-fe39-5317-98c4-65bbc476e6d2", "quiz": "c73c4125-4860-5b26-a6f2-7d1a8126bc92", "pos": 2, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nWhich enzyme catalyses the reaction?\nLactose → glucose + galactose", "options": ["Lactase", "Catalase", "Protease", "Lipase"], "marks": 1, "section": "Criterion A", "correct": 0, "model": "Catalase; lactase; lipase; protease.", "points": null}, {"id": "7b4c258c-8b8f-57f2-b1be-23c58d63e6ab", "quiz": "c73c4125-4860-5b26-a6f2-7d1a8126bc92", "pos": 3, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nWhich enzyme catalyses the reaction?\nFat → fatty acids + glycerol", "options": ["Lactase", "Catalase", "Protease", "Lipase"], "marks": 1, "section": "Criterion A", "correct": 3, "model": "Catalase; lactase; lipase; protease.", "points": null}, {"id": "a7492d5d-95af-5434-bac2-a14125c1f186", "quiz": "c73c4125-4860-5b26-a6f2-7d1a8126bc92", "pos": 4, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nWhich enzyme catalyses the reaction?\nProtein → amino acids", "options": ["Lactase", "Catalase", "Protease", "Lipase"], "marks": 1, "section": "Criterion A", "correct": 2, "model": "Catalase; lactase; lipase; protease.", "points": null}, {"id": "e8d530f3-9494-5902-bf9d-816f67e42065", "quiz": "c73c4125-4860-5b26-a6f2-7d1a8126bc92", "pos": 5, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nExplain why increasing the substrate concentration eventually has no further effect on the rate of an enzyme reaction.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "All the active sites become occupied (saturated) [1], so enzyme concentration becomes the limiting factor [1].", "points": [{"text": "All the active sites become occupied (saturated)", "any": ["active sites", "all", "saturated", "occupied"], "all": [], "marks": 1}, {"text": "Enzyme concentration becomes the limiting factor", "any": ["enzyme", "limiting", "concentration"], "all": [], "marks": 1}]}, {"id": "d4232458-f21d-5a98-8b67-4a2278e4723f", "quiz": "c73c4125-4860-5b26-a6f2-7d1a8126bc92", "pos": 6, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nOxygen produced by catalase in 1 minute: 0 % H₂O₂ 0 cm³; 1 % 10 cm³; 2 % 20 cm³; 3 % 28 cm³; 4 % 30 cm³; 5 % 30 cm³. Describe the trend and explain why the volume stops increasing.", "options": [], "marks": 3, "section": "Criterion C", "correct": null, "model": "The volume of oxygen increases as the H₂O₂ concentration increases [1], then levels off at 30 cm³ from 4 % [1], because all the catalase active sites are occupied, so enzyme concentration is limiting [1].", "points": [{"text": "The volume of oxygen increases as the H₂O₂ concentration increases", "any": ["increase", "rise"], "all": [], "marks": 1}, {"text": "Levels off at 30 cm³ from 4 %", "any": ["level", "plateau", "same", "30", "4"], "all": [], "marks": 1}, {"text": "Because all the catalase active sites are occupied, so enzyme concentration is limiting", "any": ["saturated", "active sites", "all", "enzyme", "limiting"], "all": [], "marks": 1}]}, {"id": "b7109c81-0faf-5b1e-8078-b533cf0d126d", "quiz": "c73c4125-4860-5b26-a6f2-7d1a8126bc92", "pos": 7, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nDiscuss whether biological washing powders are better for the environment than non-biological ones.", "options": [], "marks": 3, "section": "Criterion D", "correct": null, "model": "Biological powders clean at low temperatures, so less energy is used heating water [1]; the enzymes are biodegradable, but some people are allergic to them and other chemicals in the powder can still pollute rivers [1]; overall I think they are better because the energy saved is large [1].", "points": [{"text": "Biological powders clean at low temperatures, so less energy is used heating water", "any": ["low temperature", "energy", "less electricity", "cooler"], "all": [], "marks": 1}, {"text": "The enzymes are biodegradable, but some people are allergic to them and other chemicals in the powder can still pollute rivers", "any": ["biodegrad", "allerg", "rivers", "water", "packag", "phosphate"], "all": [], "marks": 1}, {"text": "Overall I think they are better because the energy saved is large", "any": ["i think", "overall", "conclusion", "better", "because"], "all": [], "marks": 1}]}, {"id": "416cb3fc-a796-5ffb-b018-9d1d8e35288a", "quiz": "699366f5-c080-5e22-bfe6-5606fae54cc1", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nExplain how glucagon raises blood glucose.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "When blood glucose is low the pancreas releases glucagon [1], which makes the liver break down glycogen into glucose and release it into the blood [1].", "points": [{"text": "When blood glucose is low the pancreas releases glucagon", "any": ["pancreas", "released", "low"], "all": [], "marks": 1}, {"text": "Which makes the liver break down glycogen into glucose and release it into the blood", "any": ["liver", "glycogen", "break down", "release glucose"], "all": [], "marks": 1}]}, {"id": "adcf437a-b802-5e64-96b1-15ae894fed17", "quiz": "699366f5-c080-5e22-bfe6-5606fae54cc1", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDescribe two treatments for type 2 diabetes.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "Controlling the diet (less sugar and refined starch) and more exercise to lose weight [1]; tablets (medicines) and, if needed, insulin injections [1].", "points": [{"text": "Controlling the diet (less sugar and refined starch) and more exercise to lose weight", "any": ["diet", "less sugar", "exercise", "weight"], "all": [], "marks": 1}, {"text": "Tablets (medicines) and, if needed, insulin injections", "any": ["tablet", "medicine", "drug", "insulin", "metformin", "exercise", "weight"], "all": [], "marks": 1}]}, {"id": "98f21c62-a795-588c-857b-8ea7d756bf29", "quiz": "699366f5-c080-5e22-bfe6-5606fae54cc1", "pos": 3, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nAfter a meal, blood glucose rose from 5.0 to 7.5 mmol/L in 30 minutes. Calculate the rate of increase per minute and the percentage increase.", "options": [], "marks": 2, "section": "Criterion C", "correct": null, "model": "Rate = (7.5 − 5.0) ÷ 30 = 0.083 mmol/L per minute [1]; percentage increase = 2.5 ÷ 5.0 × 100 = 50% [1].", "points": [{"text": "Rate = (7.5 − 5.0) ÷ 30 = 0.083 mmol/L per minute", "any": ["0.083", "0.08", "2.5 ÷ 30", "2.5/30"], "all": [], "marks": 1}, {"text": "Percentage increase = 2.5 ÷ 5.0 × 100 = 50%", "any": ["50"], "all": [], "marks": 1}]}, {"id": "970432f0-5572-5b2c-b2be-e064ed0b814d", "quiz": "699366f5-c080-5e22-bfe6-5606fae54cc1", "pos": 4, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nInsulin must be kept cool and is expensive. Discuss one way the government could help people with type 1 diabetes in rural Kenya.", "options": [], "marks": 3, "section": "Criterion D", "correct": null, "model": "The government could provide insulin free or subsidised through health insurance [1], with solar fridges at local clinics and community health workers trained to check glucose [1]; I think this should be a priority because without insulin people with type 1 diabetes die [1].", "points": [{"text": "The government could provide insulin free or subsidised through health insurance", "any": ["free", "subsid", "nhif", "sha", "insurance", "cheaper"], "all": [], "marks": 1}, {"text": "With solar fridges at local clinics and community health workers trained to check glucose", "any": ["fridge", "cool", "clinic", "storage", "solar", "community health", "training", "meter"], "all": [], "marks": 1}, {"text": "I think this should be a priority because without insulin people with type 1 diabetes die", "any": ["i think", "overall", "because", "conclusion", "should"], "all": [], "marks": 1}]}, {"id": "1c5ed866-b87d-5be3-95e3-7d3d935330de", "quiz": "17b31e9b-991c-5372-98df-3482fd7c73aa", "pos": 1, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nName the blood vessel.\nCarries deoxygenated blood to the lungs", "options": ["Aorta", "Vena cava", "Pulmonary artery", "Pulmonary vein", "Coronary artery"], "marks": 1, "section": "Criterion A", "correct": 2, "model": "Pulmonary artery; pulmonary vein; aorta; vena cava; coronary artery.", "points": null}, {"id": "661b9dcf-4493-5c8c-a8a8-14bbb3542c67", "quiz": "17b31e9b-991c-5372-98df-3482fd7c73aa", "pos": 2, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nName the blood vessel.\nCarries oxygenated blood from the lungs to the heart", "options": ["Aorta", "Vena cava", "Pulmonary artery", "Pulmonary vein", "Coronary artery"], "marks": 1, "section": "Criterion A", "correct": 3, "model": "Pulmonary artery; pulmonary vein; aorta; vena cava; coronary artery.", "points": null}, {"id": "862fd336-f102-5c8e-92f5-a64139f21ecd", "quiz": "17b31e9b-991c-5372-98df-3482fd7c73aa", "pos": 3, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nName the blood vessel.\nCarries blood from the left ventricle to the body", "options": ["Aorta", "Vena cava", "Pulmonary artery", "Pulmonary vein", "Coronary artery"], "marks": 1, "section": "Criterion A", "correct": 0, "model": "Pulmonary artery; pulmonary vein; aorta; vena cava; coronary artery.", "points": null}, {"id": "70069188-0fb6-5220-90c2-372f67623c29", "quiz": "17b31e9b-991c-5372-98df-3482fd7c73aa", "pos": 4, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nName the blood vessel.\nBrings blood from the body to the right atrium", "options": ["Aorta", "Vena cava", "Pulmonary artery", "Pulmonary vein", "Coronary artery"], "marks": 1, "section": "Criterion A", "correct": 1, "model": "Pulmonary artery; pulmonary vein; aorta; vena cava; coronary artery.", "points": null}, {"id": "5ed7d3be-e380-5fe3-a54e-25f4fd18ed4c", "quiz": "17b31e9b-991c-5372-98df-3482fd7c73aa", "pos": 5, "kind": "mcq", "prompt": "[Criterion A: Knowing and understanding]\nName the blood vessel.\nSupplies the heart muscle with blood", "options": ["Aorta", "Vena cava", "Pulmonary artery", "Pulmonary vein", "Coronary artery"], "marks": 1, "section": "Criterion A", "correct": 4, "model": "Pulmonary artery; pulmonary vein; aorta; vena cava; coronary artery.", "points": null}, {"id": "af7612a4-b592-542e-a600-d6de74981706", "quiz": "17b31e9b-991c-5372-98df-3482fd7c73aa", "pos": 6, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nCompare the structure of arteries and veins. Give three differences.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "Arteries have thick, muscular, elastic walls; veins have thin walls [1]; veins have valves but arteries do not (except at the heart) [1]; arteries have a narrow lumen and veins a wide lumen [1].", "points": [{"text": "Arteries have thick, muscular, elastic walls; veins have thin walls", "any": ["thick", "thicker wall", "muscular", "elastic"], "all": [], "marks": 1}, {"text": "Veins have valves but arteries do not (except at the heart)", "any": ["valve"], "all": [], "marks": 1}, {"text": "Arteries have a narrow lumen and veins a wide lumen", "any": ["lumen", "narrow", "wide"], "all": [], "marks": 1}]}, {"id": "efd922f6-87e0-5924-aced-fc0020f455c8", "quiz": "17b31e9b-991c-5372-98df-3482fd7c73aa", "pos": 7, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nA student's heart rate was 72 beats per minute at rest and 144 after exercise; it took 4 minutes to return to 72. Calculate the percentage increase and explain why the heart rate rose.", "options": [], "marks": 3, "section": "Criterion C", "correct": null, "model": "Increase = (144 − 72) ÷ 72 × 100 = 100% [1]; the muscles respire faster, so more oxygen and glucose must be delivered [1] and more carbon dioxide removed, so the heart pumps faster [1].", "points": [{"text": "Increase = (144 − 72) ÷ 72 × 100 = 100%", "any": ["100"], "all": [], "marks": 1}, {"text": "The muscles respire faster, so more oxygen and glucose must be delivered", "any": ["oxygen", "glucose", "respir"], "all": [], "marks": 1}, {"text": "More carbon dioxide removed, so the heart pumps faster", "any": ["carbon dioxide", "muscles", "deliver", "remove"], "all": [], "marks": 1}]}, {"id": "9c685f70-f171-57f1-a76f-0ad3fafc34ad", "quiz": "17b31e9b-991c-5372-98df-3482fd7c73aa", "pos": 8, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nDiscuss whether schools should ban the sale of deep-fried snacks such as chips and mandazi to protect students' hearts.", "options": [], "marks": 3, "section": "Criterion D", "correct": null, "model": "For: deep-fried snacks are high in fat, and habits formed young lead to obesity and coronary heart disease later [1]; against: occasional snacks are fine in a balanced diet, a ban limits choice, and local vendors lose income [1]; overall I think schools should limit them and offer healthy, affordable options instead [1].", "points": [{"text": "For: deep-fried snacks are high in fat, and habits formed young lead to obesity and coronary heart disease later", "any": ["fat", "cholesterol", "coronary", "heart disease", "obesity", "habit"], "all": [], "marks": 1}, {"text": "Against: occasional snacks are fine in a balanced diet, a ban limits choice, and local vendors lose income", "any": ["choice", "freedom", "income", "vendors", "cheap", "energy", "occasional", "balance"], "all": [], "marks": 1}, {"text": "Overall I think schools should limit them and offer healthy, affordable options instead", "any": ["i think", "overall", "conclusion", "should", "instead"], "all": [], "marks": 1}]}, {"id": "81211614-2e20-59b8-93b3-c7a2ffed74ed", "quiz": "c9c20e79-4b63-520b-8d9c-ddc9f9ce01a4", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nName the four components of blood and give one function of each.", "options": [], "marks": 4, "section": "Criterion A", "correct": null, "model": "Plasma transports dissolved substances such as glucose [1]; red blood cells carry oxygen [1]; white blood cells defend against pathogens [1]; platelets help blood to clot [1].", "points": [{"text": "Plasma transports dissolved substances such as glucose", "any": ["plasma", "transport", "dissolved"], "all": [], "marks": 1}, {"text": "Red blood cells carry oxygen", "any": ["red", "oxygen"], "all": [], "marks": 1}, {"text": "White blood cells defend against pathogens", "any": ["white", "pathogen", "defen", "antibod", "engulf"], "all": [], "marks": 1}, {"text": "Platelets help blood to clot", "any": ["platelet", "clot"], "all": [], "marks": 1}]}, {"id": "497e69b6-cc87-541b-a6f2-36cb391b2d9f", "quiz": "c9c20e79-4b63-520b-8d9c-ddc9f9ce01a4", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDescribe two ways white blood cells protect the body.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "Phagocytes engulf and digest pathogens [1]; lymphocytes make antibodies that destroy specific pathogens [1].", "points": [{"text": "Phagocytes engulf and digest pathogens", "any": ["engulf", "phagocyt", "ingest"], "all": [], "marks": 1}, {"text": "Lymphocytes make antibodies that destroy specific pathogens", "any": ["antibod", "lymphocyte"], "all": [], "marks": 1}]}, {"id": "abbe99a9-4a78-57e0-9df5-2b166ee550ae", "quiz": "c9c20e79-4b63-520b-8d9c-ddc9f9ce01a4", "pos": 3, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nA patient with blood group B needs a transfusion. Explain why group A blood must not be given.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "The patient's plasma contains anti-A antibodies [1], which would make the donated A red blood cells clump (agglutinate), blocking blood vessels [1].", "points": [{"text": "The patient's plasma contains anti-A antibodies", "any": ["anti-a", "antibodies", "antibody"], "all": [], "marks": 1}, {"text": "Which would make the donated A red blood cells clump (agglutinate), blocking blood vessels", "any": ["agglutinat", "clump", "block"], "all": [], "marks": 1}]}, {"id": "c49f8ebd-c534-5ed1-86d7-ac98a47d54b5", "quiz": "c9c20e79-4b63-520b-8d9c-ddc9f9ce01a4", "pos": 4, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nDiscuss whether all healthy adults should be encouraged to donate blood regularly.", "options": [], "marks": 3, "section": "Criterion D", "correct": null, "model": "Donated blood saves the lives of accident victims, mothers after childbirth and children with anaemia, and Kenya has a shortage [1]; donating is safe for healthy adults because the body replaces the blood within weeks, though donors must be tested and some feel tired [1]; overall I think healthy adults should be encouraged because the benefit is very large [1].", "points": [{"text": "Donated blood saves the lives of accident victims, mothers after childbirth and children with anaemia, and Kenya has a shortage", "any": ["save lives", "accident", "mothers", "malaria", "shortage", "surgery"], "all": [], "marks": 1}, {"text": "Donating is safe for healthy adults because the body replaces the blood within weeks, though donors must be tested and some feel tired", "any": ["safe", "replace", "fear", "health", "tested", "infection", "tired", "iron"], "all": [], "marks": 1}, {"text": "Overall I think healthy adults should be encouraged because the benefit is very large", "any": ["i think", "overall", "conclusion", "should", "because"], "all": [], "marks": 1}]}, {"id": "1afbf881-2da8-5e2f-a7b4-eda0f39ceb34", "quiz": "f0859644-815e-5903-9c0c-a976a64da3e2", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDefine pathogen and give an example of a disease caused by a bacterium and one caused by a virus.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "A pathogen is a microorganism that causes disease [1]; bacterium: cholera (or TB) [1]; virus: measles (or HIV) [1].", "points": [{"text": "A pathogen is a microorganism that causes disease", "any": ["microorganism", "causes disease", "organism that causes"], "all": [], "marks": 1}, {"text": "Bacterium: cholera (or TB)", "any": ["cholera", "tuberculosis", "tb", "typhoid"], "all": [], "marks": 1}, {"text": "Virus: measles (or HIV)", "any": ["measles", "hiv", "flu", "influenza", "covid", "polio", "hepatitis"], "all": [], "marks": 1}]}, {"id": "13c83ee5-9269-5ffe-a6eb-2c0dbb77fd76", "quiz": "f0859644-815e-5903-9c0c-a976a64da3e2", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nExplain why antibiotics cannot be used to treat measles.", "options": [], "marks": 1, "section": "Criterion A", "correct": null, "model": "Measles is caused by a virus, and antibiotics only kill bacteria [1].", "points": [{"text": "Measles is caused by a virus, and antibiotics only kill bacteria", "any": ["virus", "only bacteria", "do not kill viruses"], "all": [], "marks": 1}]}, {"id": "acd327be-bbfd-5ecb-9a4c-08f534998d7d", "quiz": "f0859644-815e-5903-9c0c-a976a64da3e2", "pos": 3, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nDescribe the role of memory cells in immunity.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "Memory cells remain in the blood after an infection or vaccination [1] and make antibodies much faster and in larger amounts if the same pathogen returns [1].", "points": [{"text": "Memory cells remain in the blood after an infection or vaccination", "any": ["remember", "remain", "stay", "after"], "all": [], "marks": 1}, {"text": "Make antibodies much faster and in larger amounts if the same pathogen returns", "any": ["faster", "quickly", "more antibodies", "secondary"], "all": [], "marks": 1}]}, {"id": "1678358e-191c-5d99-a8d6-77ef630c83a5", "quiz": "f0859644-815e-5903-9c0c-a976a64da3e2", "pos": 4, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nDiscuss whether vaccination against measles should be compulsory for children to join school.", "options": [], "marks": 3, "section": "Criterion D", "correct": null, "model": "For: it protects all children, including those who cannot be vaccinated, by keeping herd immunity and preventing outbreaks [1]; against: it may exclude poor children who could not reach a clinic, and some parents feel it removes their choice [1]; overall I think schools should require it but offer free vaccination at school so no child misses education [1].", "points": [{"text": "For: it protects all children, including those who cannot be vaccinated, by keeping herd immunity and preventing outbreaks", "any": ["herd immunity", "protect", "outbreak", "spread", "others"], "all": [], "marks": 1}, {"text": "Against: it may exclude poor children who could not reach a clinic, and some parents feel it removes their choice", "any": ["choice", "rights", "religion", "access", "poor", "exclude", "education"], "all": [], "marks": 1}, {"text": "Overall I think schools should require it but offer free vaccination at school so no child misses education", "any": ["i think", "overall", "conclusion", "should", "because"], "all": [], "marks": 1}]}, {"id": "fd5250f1-85a6-5979-8a50-18b46b8408b2", "quiz": "06fe14a5-8949-54c1-82e9-33aa7a30f99c", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nWrite the balanced chemical equation for aerobic respiration.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "C₆H₁₂O₆ + 6O₂ [1] → 6CO₂ + 6H₂O (+ energy) [1].", "points": [{"text": "Marking point 1", "any": ["c6h12o6", "6o2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["6h2o", "6co2"], "all": [], "marks": 1}]}, {"id": "132e9fc0-f7e9-580e-8ff3-c3a5e1024a86", "quiz": "06fe14a5-8949-54c1-82e9-33aa7a30f99c", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nState what ATP stands for and describe how it is used in cells.", "options": [], "marks": 3, "section": "Criterion A", "correct": null, "model": "Adenosine triphosphate [1]; it is made from ADP and phosphate using energy from respiration [1], then broken down to release energy where the cell needs it [1].", "points": [{"text": "Adenosine triphosphate", "any": ["adenosine triphosphate"], "all": [], "marks": 1}, {"text": "It is made from ADP and phosphate using energy from respiration", "any": ["respiration", "made", "adp"], "all": [], "marks": 1}, {"text": "Broken down to release energy where the cell needs it", "any": ["release", "broken", "energy for", "where needed"], "all": [], "marks": 1}]}, {"id": "0946c4cb-ca4c-5ecf-b463-a05ca3070bb6", "quiz": "06fe14a5-8949-54c1-82e9-33aa7a30f99c", "pos": 3, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nExplain why muscles produce lactic acid during a sprint.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "The heart and lungs cannot supply oxygen fast enough [1], so muscles also respire anaerobically, producing lactic acid [1].", "points": [{"text": "The heart and lungs cannot supply oxygen fast enough", "any": ["not enough oxygen", "oxygen", "lack"], "all": [], "marks": 1}, {"text": "Muscles also respire anaerobically, producing lactic acid", "any": ["anaerobic"], "all": [], "marks": 1}]}, {"id": "f5d839dd-000b-5a98-bb32-2e572a858bf1", "quiz": "06fe14a5-8949-54c1-82e9-33aa7a30f99c", "pos": 4, "kind": "short", "prompt": "[Criterion C: Processing and evaluating]\nIn yeast, 30 cm³ of CO₂ was produced in 5 minutes at 35 °C and 12 cm³ in 5 minutes at 20 °C. Calculate both rates and explain the difference.", "options": [], "marks": 3, "section": "Criterion C", "correct": null, "model": "At 35 °C: 30 ÷ 5 = 6 cm³ per minute [1]; at 20 °C: 12 ÷ 5 = 2.4 cm³ per minute [1]; at the higher temperature the respiration enzymes and molecules have more kinetic energy, so reactions are faster [1].", "points": [{"text": "At 35 °C: 30 ÷ 5 = 6 cm³ per minute", "any": ["6"], "all": [], "marks": 1}, {"text": "At 20 °C: 12 ÷ 5 = 2.4 cm³ per minute", "any": ["2.4"], "all": [], "marks": 1}, {"text": "At the higher temperature the respiration enzymes and molecules have more kinetic energy, so reactions are faster", "any": ["enzyme", "kinetic", "collision", "faster", "temperature"], "all": [], "marks": 1}]}, {"id": "d90d20b2-26d7-5401-aaa0-baf1905642c1", "quiz": "0324e067-4cf8-5d82-8948-f990a3218b39", "pos": 1, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nTrace the path of an amino acid from a meal of beans to a muscle cell, naming the systems involved.", "options": [], "marks": 4, "section": "Criterion A", "correct": null, "model": "Protein in beans is digested by protease into amino acids (digestive system) [1]; they are absorbed into the blood in the villi of the small intestine [1]; they are carried by the hepatic portal vein to the liver and pumped by the heart (cardiovascular system) [1]; they leave the capillaries and enter the muscle cell [1].", "points": [{"text": "Protein in beans is digested by protease into amino acids (digestive system)", "any": ["protease", "digest", "protein"], "all": [], "marks": 1}, {"text": "They are absorbed into the blood in the villi of the small intestine", "any": ["absorb", "villi", "small intestine"], "all": [], "marks": 1}, {"text": "They are carried by the hepatic portal vein to the liver and pumped by the heart (cardiovascular system)", "any": ["blood", "hepatic portal", "liver", "heart"], "all": [], "marks": 1}, {"text": "They leave the capillaries and enter the muscle cell", "any": ["capillar", "diffus", "muscle cell", "cardiovascular"], "all": [], "marks": 1}]}, {"id": "81f87554-79bf-5a19-b338-c370e73fb266", "quiz": "0324e067-4cf8-5d82-8948-f990a3218b39", "pos": 2, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nExplain why both the respiratory system and the digestive system are needed for aerobic respiration in a muscle cell.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "The respiratory system supplies oxygen [1] and the digestive system supplies glucose; both are reactants of aerobic respiration [1].", "points": [{"text": "The respiratory system supplies oxygen", "any": ["oxygen", "lungs"], "all": [], "marks": 1}, {"text": "The digestive system supplies glucose; both are reactants of aerobic respiration", "any": ["glucose", "food"], "all": [], "marks": 1}]}, {"id": "8720e6a2-ebdc-5580-8972-24acedb9fa4a", "quiz": "0324e067-4cf8-5d82-8948-f990a3218b39", "pos": 3, "kind": "short", "prompt": "[Criterion A: Knowing and understanding]\nExplain why the heart rate rises after a large meal.", "options": [], "marks": 2, "section": "Criterion A", "correct": null, "model": "More blood is sent to the gut [1] to supply oxygen for the digestive muscles and to carry away the absorbed food [1].", "points": [{"text": "More blood is sent to the gut", "any": ["blood", "gut", "intestine", "digest"], "all": [], "marks": 1}, {"text": "To supply oxygen for the digestive muscles and to carry away the absorbed food", "any": ["absorb", "oxygen", "more blood flow", "muscles of the gut", "transport"], "all": [], "marks": 1}]}, {"id": "e4810de3-37b6-5d50-b0e2-024de72d3146", "quiz": "0324e067-4cf8-5d82-8948-f990a3218b39", "pos": 4, "kind": "short", "prompt": "[Criterion D: Reflecting on the impacts of science]\nUse the statement of inquiry (\"Evidence of healthy wellbeing is a consequence of the proper functioning of systems\") to explain why doctors measure more than one thing (e.g. blood pressure, blood glucose and haemoglobin) at a check-up.", "options": [], "marks": 3, "section": "Criterion D", "correct": null, "model": "Each measurement gives evidence about how a different system is working [1]: blood pressure (cardiovascular), blood glucose (endocrine and digestive), haemoglobin (blood and oxygen supply) [1]; because systems depend on each other, a problem in one can affect the others, so wellbeing depends on all of them together [1].", "points": [{"text": "Each measurement gives evidence about how a different system is working", "any": ["evidence", "measure", "indicator"], "all": [], "marks": 1}, {"text": "Blood pressure (cardiovascular), blood glucose (endocrine and digestive), haemoglobin (blood and oxygen supply)", "any": ["system", "heart", "blood", "pancreas", "cardiovascular", "digestive", "endocrine"], "all": [], "marks": 1}, {"text": "Because systems depend on each other, a problem in one can affect the others, so wellbeing depends on all of them together", "any": ["together", "interdepend", "one system affects", "whole", "linked"], "all": [], "marks": 1}]}], "subject": "MYP Biology", "level": "Grade 9", "unit": "MYP 4 · Biology · Digestion, enzymes, circulation and respiration", "first": 105, "cfirst": 32, "k": 12}$j$::jsonb; t uuid := (d->'topic'->>'id')::uuid; begin
  if (d->'topic'->>'new')::boolean then
    insert into public.topics (id, subject_id, programme, name, summary, sort_order, parent_id) select t, s.id, d->'topic'->>'programme', d->'topic'->>'name', d->'topic'->>'summary', (d->'topic'->>'sort')::int, (d->'topic'->>'parent')::uuid
      from public.subjects s where s.name = 'MYP Science' on conflict (id) do nothing;
  end if;
  insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select (l->>'id')::uuid, t, l->>'title', l->>'summary', l->>'url', l->>'ext', (l->>'max')::int, (l->>'sort')::int from jsonb_array_elements(d->'lessons') l
    on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
  insert into public.lesson_specs (lesson, title, spec, updated_at) select l->>'ext', l->>'title', l->'spec', now() from jsonb_array_elements(d->'lessons') l
    on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
  if not exists (select 1 from public.materials m join jsonb_array_elements(d->'lessons') l on m.path = l->>'url') then   -- make room once: everything after the anchor moves down
    update public.materials set sort = sort + (d->>'k')::int where sort >= (d->>'first')::int;
    update public.class_materials cm set sort = cm.sort + (d->>'k')::int where cm.sort >= (d->>'cfirst')::int and cm.class_id in (select a.class_id from public.class_materials a where a.path = d->>'anchor');
  end if;
  insert into public.materials (path, lesson_id, title, kind, subject, level, unit, sort) select l->>'url', l->>'ext', l->>'title', 'lesson', d->>'subject', d->>'level', d->>'unit', (l->>'msort')::int from jsonb_array_elements(d->'lessons') l
    on conflict (path) do update set lesson_id = excluded.lesson_id, title = excluded.title, kind = excluded.kind, subject = excluded.subject, level = excluded.level, unit = excluded.unit, sort = excluded.sort;
  insert into public.class_materials (class_id, path, sort) select a.class_id, l->>'url', (l->>'csort')::int from jsonb_array_elements(d->'lessons') l join public.class_materials a on a.path = d->>'anchor' on conflict do nothing;
  insert into public.quizzes (id, topic_id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by)
    select (q->>'id')::uuid, t, q->>'title', q->>'instr', null, 2, true, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e' from jsonb_array_elements(d->'quizzes') q
    on conflict (id) do update set title = excluded.title, instructions = excluded.instructions, topic_id = excluded.topic_id;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quizzes' and column_name = 'subject') then
    update public.quizzes set subject = 'Biology' where id in (select (q->>'id')::uuid from jsonb_array_elements(d->'quizzes') q);
  end if;
  insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) select (q->>'id')::uuid, t, q->>'kind', q->>'prompt', q->'options', (q->>'marks')::int, q->>'section', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e' from jsonb_array_elements(d->'questions') q
    on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section;
  insert into public.question_answers (question_id, correct_option, model_answer, mark_scheme, points, explanation)
    select (q->>'id')::uuid, (q->>'correct')::int, case when q->>'kind' = 'mcq' then q->'options'->>((q->>'correct')::int) else q->>'model' end, case when q->>'kind' = 'mcq' then null else q->>'model' end,
           case when q->>'kind' = 'mcq' then null else q->'points' end, q->>'model' from jsonb_array_elements(d->'questions') q
    on conflict (question_id) do update set correct_option = excluded.correct_option, model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
  insert into public.quiz_questions (quiz_id, question_id, position) select (q->>'quiz')::uuid, (q->>'id')::uuid, (q->>'pos')::int from jsonb_array_elements(d->'questions') q
    on conflict (quiz_id, question_id) do update set position = excluded.position;
  insert into public.quiz_classes (quiz_id, class_id, published, published_at, published_by)
    select (q->>'id')::uuid, c.id, c.teacher_id = 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e', case when c.teacher_id = 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e' then now() end, case when c.teacher_id = 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e' then 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e'::uuid end
      from jsonb_array_elements(d->'quizzes') q cross join public.classes c where c.id in (select a.class_id from public.class_materials a where a.path = d->>'anchor')
    on conflict do nothing;
end $do$;
select (select count(*) from public.lessons where external_id like 'G9-BIO-DCR-L%') as lessons, (select count(*) from public.lesson_specs where lesson like 'G9-BIO-DCR-L%') as specs, (select count(*) from public.materials where path like '/g9-bio-dcr-%') as materials, (select count(*) from public.class_materials where path like '/g9-bio-dcr-%') as class_links, (select count(*) from public.quizzes where topic_id = '074d8b95-40b8-583a-9b76-9f324e19c12a' and title like '%exam-style questions') as exam_sets, (select count(*) from public.quiz_questions qq join public.quizzes q on q.id = qq.quiz_id where q.topic_id = '074d8b95-40b8-583a-9b76-9f324e19c12a' and q.title like '%exam-style questions') as exam_questions;
